CREATE TABLE public.tariff_plans (id text PRIMARY KEY CHECK(id IN ('free','basic','premium')), name text NOT NULL, price_cents integer NOT NULL DEFAULT 0 CHECK(price_cents>=0), manual_limit integer CHECK(manual_limit>=0), ocr_limit integer NOT NULL DEFAULT 0 CHECK(ocr_limit>=0), documents boolean NOT NULL DEFAULT true, voice boolean NOT NULL DEFAULT false, logo boolean NOT NULL DEFAULT false, advanced_reports boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.tariff_plans TO anon, authenticated; GRANT ALL ON public.tariff_plans TO service_role;
ALTER TABLE public.tariff_plans ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public tariff catalog" ON public.tariff_plans FOR SELECT TO anon, authenticated USING(true);
INSERT INTO public.tariff_plans SELECT * FROM (VALUES ('free','Free',0,50,3,true,false,false,false),('basic','Basic',990,NULL::integer,20,true,false,false,false),('premium','Premium',1990,NULL::integer,150,true,true,true,true)) AS p;
CREATE TABLE public.platform_operators(user_id uuid PRIMARY KEY REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.platform_operators TO authenticated; GRANT ALL ON public.platform_operators TO service_role;
ALTER TABLE public.platform_operators ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own operator grant" ON public.platform_operators FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION private.is_platform_operator() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM platform_operators WHERE user_id=auth.uid()) $$;
CREATE TABLE public.subscriptions (organization_id uuid PRIMARY KEY REFERENCES public.organizations(id), plan_id text NOT NULL DEFAULT 'free' REFERENCES public.tariff_plans(id), status text NOT NULL DEFAULT 'free' CHECK(status IN ('free','trialing','active','past_due','canceled','expired')), starts_at timestamptz NOT NULL DEFAULT now(), period_end timestamptz, renews_at timestamptz, source text NOT NULL DEFAULT 'manual' CHECK(source IN ('manual','provider')), external_customer_ref text, external_subscription_ref text UNIQUE, trial_used boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now(), CHECK(period_end IS NULL OR period_end>starts_at));
GRANT SELECT ON public.subscriptions TO authenticated; GRANT ALL ON public.subscriptions TO service_role;
ALTER TABLE public.subscriptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Members read subscriptions" ON public.subscriptions FOR SELECT TO authenticated USING(private.is_org_member(organization_id) OR private.is_platform_operator());
INSERT INTO public.subscriptions(organization_id) SELECT id FROM public.organizations;
CREATE FUNCTION private.initialize_subscription() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO subscriptions(organization_id) VALUES(NEW.id); RETURN NEW; END $$;
CREATE TRIGGER initialize_subscription AFTER INSERT ON public.organizations FOR EACH ROW EXECUTE FUNCTION private.initialize_subscription();
CREATE TABLE public.subscription_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid REFERENCES public.organizations(id), administrator uuid NOT NULL, reason text NOT NULL, before_value jsonb, after_value jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.subscription_audit TO authenticated; GRANT ALL ON public.subscription_audit TO service_role;
ALTER TABLE public.subscription_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Operator reads audit" ON public.subscription_audit FOR SELECT TO authenticated USING(private.is_platform_operator());
CREATE TABLE public.ocr_usage(id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES public.organizations(id), user_id uuid NOT NULL, period_start date NOT NULL, image_hash text NOT NULL, state text NOT NULL DEFAULT 'reserved' CHECK(state IN ('reserved','confirmed','refunded')), result jsonb, reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.ocr_usage TO authenticated; GRANT ALL ON public.ocr_usage TO service_role;
ALTER TABLE public.ocr_usage ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Members read scan usage" ON public.ocr_usage FOR SELECT TO authenticated USING(private.is_org_member(organization_id) OR private.is_platform_operator());
CREATE INDEX ocr_usage_period ON public.ocr_usage(organization_id,period_start,state);
CREATE FUNCTION private.effective_plan(_org uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN status IN ('active','trialing','canceled') AND starts_at<=now() AND period_end>now() THEN plan_id ELSE 'free' END FROM subscriptions WHERE organization_id=_org $$;
CREATE FUNCTION public.tariff_feature(_org uuid,_feature text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p tariff_plans%ROWTYPE; BEGIN IF NOT private.is_org_member(_org) THEN RAISE EXCEPTION 'Keine Berechtigung.'; END IF; SELECT * INTO p FROM tariff_plans WHERE id=private.effective_plan(_org); RETURN CASE _feature WHEN 'voice' THEN p.voice WHEN 'logo' THEN p.logo WHEN 'documents' THEN p.documents WHEN 'advanced_reports' THEN p.advanced_reports ELSE false END; END $$;
REVOKE ALL ON FUNCTION public.tariff_feature(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.tariff_feature(uuid,text) TO authenticated;
ALTER TABLE public.transactions ADD COLUMN capture_source text NOT NULL DEFAULT 'manual' CHECK(capture_source IN ('manual','voice'));
CREATE FUNCTION private.enforce_transaction_tariff() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE lim integer; cnt integer; BEGIN
 IF TG_OP='UPDATE' AND NEW.organization_id<>OLD.organization_id THEN RAISE EXCEPTION 'Unternehmen einer Buchung ist unveränderlich.'; END IF;
 IF NEW.recurring_expense_id IS NOT NULL AND TG_OP='INSERT' AND current_setting('keshja.recurring',true) IS DISTINCT FROM 'on' THEN RAISE EXCEPTION 'Wiederkehrende Buchungen nur über Fixkosten buchen.'; END IF;
 IF NEW.capture_source='voice' AND (TG_OP='INSERT' OR OLD.capture_source IS DISTINCT FROM NEW.capture_source) AND NOT public.tariff_feature(NEW.organization_id,'voice') THEN RAISE EXCEPTION 'Sprachbuchung ist im Premium-Tarif verfügbar.'; END IF;
 IF NEW.payment_id IS NOT NULL OR NEW.recurring_expense_id IS NOT NULL OR NEW.receipt_id IS NOT NULL THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND OLD.payment_id IS NULL AND OLD.recurring_expense_id IS NULL AND OLD.receipt_id IS NULL THEN RETURN NEW; END IF;
 PERFORM 1 FROM organizations WHERE id=NEW.organization_id FOR UPDATE;
 SELECT manual_limit INTO lim FROM tariff_plans WHERE id=private.effective_plan(NEW.organization_id);
 IF lim IS NOT NULL THEN SELECT count(*) INTO cnt FROM transactions WHERE organization_id=NEW.organization_id AND payment_id IS NULL AND recurring_expense_id IS NULL AND receipt_id IS NULL AND id<>NEW.id; IF cnt>=lim THEN RAISE EXCEPTION 'Free-Limit von % aktiven manuellen Buchungen erreicht.',lim; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER transactions_tariff BEFORE INSERT OR UPDATE ON public.transactions FOR EACH ROW EXECUTE FUNCTION private.enforce_transaction_tariff();
CREATE FUNCTION private.enforce_document_tariff() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.kind IN ('invoice','quote') AND (TG_OP='INSERT' OR (OLD.status='draft' AND NEW.status='issued')) AND NOT public.tariff_feature(NEW.organization_id,'documents') THEN RAISE EXCEPTION 'Neue Angebote und Rechnungen sind in diesem Tarif nicht verfügbar.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER documents_tariff BEFORE INSERT OR UPDATE ON public.documents FOR EACH ROW EXECUTE FUNCTION private.enforce_document_tariff();
CREATE FUNCTION public.reserve_ocr(_org uuid,_user uuid,_request uuid,_hash text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE old ocr_usage%ROWTYPE; lim integer; used integer; period date:=date_trunc('month',now() AT TIME ZONE 'UTC')::date; BEGIN
 IF NOT EXISTS(SELECT 1 FROM organization_members WHERE organization_id=_org AND user_id=_user) THEN RAISE EXCEPTION 'Keine Berechtigung.'; END IF; PERFORM 1 FROM organizations WHERE id=_org FOR UPDATE; SELECT * INTO old FROM ocr_usage WHERE id=_request;
 IF old.id IS NOT NULL THEN IF old.organization_id<>_org OR old.user_id<>_user OR old.image_hash<>_hash THEN RAISE EXCEPTION 'Ungültige Scan-Wiederholung.'; END IF; RETURN jsonb_build_object('state',old.state,'result',old.result); END IF;
 SELECT ocr_limit INTO lim FROM tariff_plans WHERE id=private.effective_plan(_org); SELECT count(*) INTO used FROM ocr_usage WHERE organization_id=_org AND period_start=period AND state<>'refunded'; IF used>=coalesce(lim,0) THEN RAISE EXCEPTION 'Monatliches KI-Belegscan-Kontingent ausgeschöpft.'; END IF;
 INSERT INTO ocr_usage(id,organization_id,user_id,period_start,image_hash) VALUES(_request,_org,_user,period,_hash); RETURN jsonb_build_object('state','new'); END $$;
CREATE FUNCTION public.finish_ocr(_request uuid,_state text,_result jsonb DEFAULT NULL,_reason text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _state NOT IN ('confirmed','refunded') THEN RAISE EXCEPTION 'Ungültiger Zustand'; END IF; IF _state='refunded' AND coalesce(_reason,'')='' THEN RAISE EXCEPTION 'Erstattungsgrund erforderlich'; END IF; UPDATE ocr_usage SET state=_state,result=_result,reason=_reason,updated_at=now() WHERE id=_request AND state='reserved'; END $$;
REVOKE ALL ON FUNCTION public.reserve_ocr(uuid,uuid,uuid,text), public.finish_ocr(uuid,text,jsonb,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.reserve_ocr(uuid,uuid,uuid,text), public.finish_ocr(uuid,text,jsonb,text) TO service_role;
CREATE FUNCTION public.tariff_overview(_org uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s subscriptions%ROWTYPE; p tariff_plans%ROWTYPE; used integer; manual integer; BEGIN IF NOT private.is_org_member(_org) AND NOT private.is_platform_operator() THEN RAISE EXCEPTION 'Keine Berechtigung.'; END IF; SELECT * INTO s FROM subscriptions WHERE organization_id=_org; SELECT * INTO p FROM tariff_plans WHERE id=private.effective_plan(_org); SELECT count(*) INTO used FROM ocr_usage WHERE organization_id=_org AND period_start=date_trunc('month',now() AT TIME ZONE 'UTC')::date AND state<>'refunded'; SELECT count(*) INTO manual FROM transactions WHERE organization_id=_org AND payment_id IS NULL AND recurring_expense_id IS NULL AND receipt_id IS NULL; RETURN jsonb_build_object('subscription',to_jsonb(s),'plan',to_jsonb(p),'ocr_used',used,'manual_used',manual,'period_start',date_trunc('month',now() AT TIME ZONE 'UTC')::date); END $$;
REVOKE ALL ON FUNCTION public.tariff_overview(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.tariff_overview(uuid) TO authenticated;
CREATE FUNCTION public.operator_dashboard() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT private.is_platform_operator() THEN RAISE EXCEPTION 'Nur für den autorisierten Betreiber.'; END IF; RETURN jsonb_build_object('organizations',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',o.id,'name',o.name,'tariff',public.tariff_overview(o.id))),'[]') FROM organizations o),'users',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',p.id,'display_name',p.display_name,'memberships',(SELECT coalesce(jsonb_agg(jsonb_build_object('organization_id',m.organization_id,'role',m.role)),'[]') FROM organization_members m WHERE m.user_id=p.id))),'[]') FROM profiles p),'audit',(SELECT coalesce(jsonb_agg(a),'[]') FROM (SELECT * FROM subscription_audit ORDER BY created_at DESC LIMIT 100) a)); END $$;
CREATE FUNCTION public.operator_set_subscription(_org uuid,_plan text,_status text,_start timestamptz,_end timestamptz,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE old subscriptions%ROWTYPE; fresh subscriptions%ROWTYPE; BEGIN IF NOT private.is_platform_operator() THEN RAISE EXCEPTION 'Nur für den autorisierten Betreiber.'; END IF; IF length(btrim(coalesce(_reason,'')))<3 THEN RAISE EXCEPTION 'Bitte einen Änderungsgrund angeben.'; END IF; IF _status='free' AND _plan<>'free' OR _status<>'free' AND (_end IS NULL OR _end<=_start) THEN RAISE EXCEPTION 'Gültigen Tarifzeitraum angeben.'; END IF;
 SELECT * INTO old FROM subscriptions WHERE organization_id=_org FOR UPDATE; IF _status='canceled' AND (old.period_end IS DISTINCT FROM _end OR old.plan_id<>_plan OR old.starts_at IS DISTINCT FROM _start) THEN RAISE EXCEPTION 'Kündigung muss den bestehenden bezahlten Zeitraum erhalten.'; END IF;
 UPDATE subscriptions SET plan_id=_plan,status=_status,starts_at=_start,period_end=_end,renews_at=NULL,source='manual',trial_used=trial_used OR _status='trialing',updated_at=now() WHERE organization_id=_org RETURNING * INTO fresh; IF fresh.organization_id IS NULL THEN RAISE EXCEPTION 'Unternehmen nicht gefunden.'; END IF;
 INSERT INTO subscription_audit(organization_id,administrator,reason,before_value,after_value) VALUES(_org,auth.uid(),_reason,to_jsonb(old),to_jsonb(fresh)); END $$;
CREATE FUNCTION public.operator_set_plan(_plan text,_values jsonb,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE old tariff_plans%ROWTYPE; fresh tariff_plans%ROWTYPE; BEGIN IF NOT private.is_platform_operator() THEN RAISE EXCEPTION 'Nur für den autorisierten Betreiber.'; END IF; IF length(btrim(coalesce(_reason,'')))<3 THEN RAISE EXCEPTION 'Grund erforderlich.'; END IF; SELECT * INTO old FROM tariff_plans WHERE id=_plan FOR UPDATE; UPDATE tariff_plans SET price_cents=(_values->>'price_cents')::integer,manual_limit=(_values->>'manual_limit')::integer,ocr_limit=(_values->>'ocr_limit')::integer,documents=(_values->>'documents')::boolean,voice=(_values->>'voice')::boolean,logo=(_values->>'logo')::boolean,advanced_reports=(_values->>'advanced_reports')::boolean WHERE id=_plan RETURNING * INTO fresh; IF fresh.id IS NULL THEN RAISE EXCEPTION 'Tarif nicht gefunden'; END IF; INSERT INTO subscription_audit(administrator,reason,before_value,after_value) VALUES(auth.uid(),_reason,to_jsonb(old),to_jsonb(fresh)); END $$;
REVOKE ALL ON FUNCTION public.operator_dashboard(),public.operator_set_subscription(uuid,text,text,timestamptz,timestamptz,text),public.operator_set_plan(text,jsonb,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.operator_dashboard(),public.operator_set_subscription(uuid,text,text,timestamptz,timestamptz,text),public.operator_set_plan(text,jsonb,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.book_due_recurring_expenses(_org uuid) RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE f record; _d date; _step interval; _n int; _count int:=0; _rows int; BEGIN IF NOT private.is_org_member(_org) THEN RAISE EXCEPTION 'Keine Berechtigung.'; END IF; PERFORM set_config('keshja.recurring','on',true); FOR f IN SELECT * FROM fixed_costs WHERE organization_id=_org AND active LOOP _step:=CASE f.interval WHEN 'jährlich' THEN interval '1 year' WHEN 'vierteljährlich' THEN interval '3 months' ELSE interval '1 month' END; _n:=0; LOOP _d:=(f.start_date+_step*_n)::date; EXIT WHEN _d>current_date OR (f.end_date IS NOT NULL AND _d>f.end_date) OR _n>=240; INSERT INTO transactions(organization_id,type,amount,booking_date,category,description,status,recurring_expense_id,recurring_period) VALUES(_org,'expense',f.amount,_d,f.category,f.name,'offen',f.id,_d) ON CONFLICT(recurring_expense_id,recurring_period) WHERE recurring_expense_id IS NOT NULL DO NOTHING; GET DIAGNOSTICS _rows=ROW_COUNT; _count:=_count+_rows; _n:=_n+1; END LOOP; END LOOP; PERFORM set_config('keshja.recurring','off',true); RETURN _count; END $$;
ALTER POLICY "org members read logos" ON storage.objects USING(bucket_id='org-logos' AND private.is_org_member(((storage.foldername(name))[1])::uuid) AND public.tariff_feature(((storage.foldername(name))[1])::uuid,'logo'));
ALTER POLICY "org admins upload logos" ON storage.objects WITH CHECK(bucket_id='org-logos' AND private.is_org_admin(((storage.foldername(name))[1])::uuid) AND public.tariff_feature(((storage.foldername(name))[1])::uuid,'logo'));
ALTER POLICY "org admins update logos" ON storage.objects USING(bucket_id='org-logos' AND private.is_org_admin(((storage.foldername(name))[1])::uuid) AND public.tariff_feature(((storage.foldername(name))[1])::uuid,'logo')) WITH CHECK(bucket_id='org-logos' AND private.is_org_admin(((storage.foldername(name))[1])::uuid) AND public.tariff_feature(((storage.foldername(name))[1])::uuid,'logo'));